#include <iostream>
using namespace std;

// 正确的取余函数，保证结果为非负数
long long mod(long long a, long long m) {
    return ((a % m) + m) % m;
}

int main() {
    long long a, m;
    cin >> a >> m;
    cout << mod(a, m) << endl;

    // 验证几个例子
    cout << "7 mod 3 = " << mod(7, 3) << endl;    // 1
    cout << "-7 mod 3 = " << mod(-7, 3) << endl;   // 2
    cout << "-1 mod 5 = " << mod(-1, 5) << endl;   // 4
    cout << "12 mod 5 = " << mod(12, 5) << endl;   // 2
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

ll mod(ll a, ll m) {
    return ((a % m) + m) % m;
}

// 模加法
ll modAdd(ll a, ll b, ll m) {
    return (mod(a, m) + mod(b, m)) % m;
}

// 模减法
ll modSub(ll a, ll b, ll m) {
    return (mod(a, m) - mod(b, m) + m) % m;
}

// 模乘法
ll modMul(ll a, ll b, ll m) {
    return (mod(a, m) * mod(b, m)) % m;
}

int main() {
    ll a = 1234567890;
    ll b = 9876543210;
    ll m = 1000000007;

    cout << "(a + b) mod m = " << modAdd(a, b, m) << endl;
    cout << "(a - b) mod m = " << modSub(a, b, m) << endl;
    cout << "(a * b) mod m = " << modMul(a, b, m) << endl;

    // 计算阶乘取模: n! mod m
    int n = 20;
    ll fact = 1;
    for (int i = 2; i <= n; i++) {
        fact = (fact * i) % m;
    }
    cout << n << "! mod m = " << fact << endl;
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

// 判断 a 和 b 是否在模 m 下同余
bool isCongruent(ll a, ll b, ll m) {
    return ((a - b) % m + m) % m == 0;
}

int main() {
    ll a, b, m;
    cin >> a >> b >> m;

    if (isCongruent(a, b, m)) {
        cout << a << " ≡ " << b << " (mod " << m << ")" << endl;
    } else {
        cout << a << " 和 " << b << " 在模 " << m << " 下不同余" << endl;
    }

    // 利用同余性质简化计算
    // 求 2^100 mod 7
    // 因为 2^3 = 8 ≡ 1 (mod 7)
    // 所以 2^100 = 2^(3*33+1) = (2^3)^33 * 2 ≡ 1^33 * 2 = 2 (mod 7)
    ll result = 1;
    ll base = 2;
    ll exp = 100;
    m = 7;
    while (exp > 0) {
        if (exp % 2 == 1) result = result * base % m;
        base = base * base % m;
        exp /= 2;
    }
    cout << "2^100 mod 7 = " << result << endl;
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

// 快速幂：计算 a^n
ll quickPow(ll a, ll n) {
    ll res = 1;
    ll base = a;
    while (n > 0) {
        if (n % 2 == 1) {
            res = res * base;
        }
        base = base * base;
        n /= 2;
    }
    return res;
}

// 快速幂的递归写法
ll quickPowRecursive(ll a, ll n) {
    if (n == 0) return 1;
    ll half = quickPowRecursive(a, n / 2);
    if (n % 2 == 0) {
        return half * half;
    } else {
        return half * half * a;
    }
}

int main() {
    ll a, n;
    cin >> a >> n;
    cout << a << "^" << n << " = " << quickPow(a, n) << endl;
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

// 模幂运算：计算 a^n mod m
ll modPow(ll a, ll n, ll m) {
    ll res = 1;
    a = a % m;  // 先取模
    while (n > 0) {
        if (n % 2 == 1) {
            res = (res * a) % m;
        }
        a = (a * a) % m;
        n /= 2;
    }
    return res;
}

int main() {
    ll a, n, m;
    cin >> a >> n >> m;
    cout << a << "^" << n << " mod " << m << " = " << modPow(a, n, m) << endl;

    // 示例：计算 2^1000000000 mod 1000000007
    cout << "2^1000000000 mod 1000000007 = "
         << modPow(2, 1000000000LL, 1000000007LL) << endl;
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

// 方法1：费马小定理求逆元（m必须是质数）
ll modPow(ll a, ll n, ll m) {
    ll res = 1;
    a = a % m;
    while (n > 0) {
        if (n % 2 == 1) res = (res * a) % m;
        a = (a * a) % m;
        n /= 2;
    }
    return res;
}

ll invFermat(ll b, ll m) {
    return modPow(b, m - 2, m);
}

// 方法2：扩展欧几里得求逆元
ll extGcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll g = extGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

ll invExtGcd(ll b, ll m) {
    ll x, y;
    ll g = extGcd(b, m, x, y);
    return ((x % m) + m) % m;
}

int main() {
    ll b, m;
    cin >> b >> m;

    // 费马小定理法（m为质数时使用）
    cout << "逆元(费马): " << invFermat(b, m) << endl;

    // 扩展欧几里得法
    cout << "逆元(extGcd): " << invExtGcd(b, m) << endl;

    // 验证: b * inv ≡ 1 (mod m)
    ll inv = invFermat(b, m);
    cout << "验证: " << b << " * " << inv << " mod " << m
         << " = " << (b % m * inv % m) % m << endl;
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

ll modPow(ll a, ll n, ll m) {
    ll res = 1;
    a = a % m;
    while (n > 0) {
        if (n % 2 == 1) res = (res * a) % m;
        a = (a * a) % m;
        n /= 2;
    }
    return res;
}

int main() {
    ll a, p;
    cin >> a >> p;

    // 验证费马小定理: a^(p-1) mod p = 1
    cout << a << "^(" << p - 1 << ") mod " << p << " = "
         << modPow(a, p - 1, p) << endl;

    // 应用1：求逆元
    ll inv = modPow(a, p - 2, p);
    cout << a << " 的逆元 mod " << p << " = " << inv << endl;
    cout << "验证: " << a << " * " << inv << " mod " << p
         << " = " << (a % p * (inv % p)) % p << endl;

    // 应用2：简化大指数
    // 计算 a^(10^18) mod p
    ll n = 1000000000000000000LL;
    ll reduced_n = n % (p - 1);  // 利用费马小定理减小指数
    cout << a << "^(10^18) mod " << p << " = "
         << modPow(a, reduced_n, p) << endl;
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

// 扩展欧几里得算法
// 返回 gcd(a,b)，同时求出 x, y 使得 ax + by = gcd(a,b)
ll extGcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll g = extGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

// 求 a 在模 m 下的逆元（需要 gcd(a,m)=1）
ll modInverse(ll a, ll m) {
    ll x, y;
    ll g = extGcd(a, m, x, y);
    return ((x % m) + m) % m;
}

// 求解 ax ≡ c (mod m)，返回最小非负解
ll solveLinear(ll a, ll c, ll m) {
    ll x, y;
    ll g = extGcd(a, m, x, y);
    if (c % g != 0) return -1;  // 无解
    x = x * (c / g);
    ll m2 = m / g;
    return ((x % m2) + m2) % m2;
}

int main() {
    ll a, b;
    cin >> a >> b;

    ll x, y;
    ll g = extGcd(a, b, x, y);
    cout << "gcd(" << a << ", " << b << ") = " << g << endl;
    cout << "x = " << x << ", y = " << y << endl;
    cout << "验证: " << a << "*" << x << " + " << b << "*" << y
         << " = " << a * x + b * y << endl;

    // 求逆元
    ll m;
    cin >> m;
    cout << "逆元: " << modInverse(a, m) << endl;
    return 0;
}

#include <iostream>
using namespace std;

typedef long long ll;

ll extGcd(ll a, ll b, ll &x, ll &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    ll x1, y1;
    ll g = extGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

ll modInverse(ll a, ll m) {
    ll x, y;
    extGcd(a, m, x, y);
    return ((x % m) + m) % m;
}

// 中国剩余定理
// m[] 是模数数组，r[] 是余数数组，n 是方程个数
// 要求模数两两互质
ll CRT(ll m[], ll r[], int n) {
    ll M = 1;
    for (int i = 0; i < n; i++) {
        M *= m[i];
    }

    ll x = 0;
    for (int i = 0; i < n; i++) {
        ll Mi = M / m[i];
        ll ti = modInverse(Mi, m[i]);
        x = (x + r[i] % m[i] * (Mi % M) % M * (ti % M) % M) % M;
    }

    return (x + M) % M;
}

int main() {
    int n;
    cin >> n;
    ll m[100], r[100];
    for (int i = 0; i < n; i++) {
        cin >> m[i] >> r[i];
    }
    cout << CRT(m, r, n) << endl;
    return 0;
}
